const input = typeof query === 'string' ? JSON.parse(query) : query;
const date = String(input.date || '').trim();
const time = String(input.time || '').trim();
const platform = String(input.platform || '').trim().toLowerCase();
let rows = [];
try {
  rows = typeof input.schedule_json === 'string' ? JSON.parse(input.schedule_json) : (input.schedule_json || []);
} catch (e) {
  return JSON.stringify({ ok: false, error: 'schedule_json is not valid JSON' });
}
if (!Array.isArray(rows)) rows = [];

const slot = DateTime.fromISO(date + 'T' + time, { zone: 'Asia/Amman' });
if (!slot.isValid) {
  return JSON.stringify({ ok: false, error: 'Invalid date or time. Use YYYY-MM-DD and HH:mm (24h).' });
}
const now = DateTime.now().setZone('Asia/Amman');
const isPast = slot < now;

const conflicts = rows.filter(r => {
  const status = String(r.status || '').toLowerCase();
  if (status === 'cancelled' || status === 'canceled') return false;
  return String(r.date || '').trim() === date
    && String(r.time || '').trim() === time
    && String(r.platform || '').trim().toLowerCase() === platform;
});

return JSON.stringify({
  ok: !isPast && conflicts.length === 0,
  now: now.toFormat('yyyy-MM-dd HH:mm'),
  slot: slot.toFormat('cccc yyyy-MM-dd HH:mm'),
  is_past: isPast,
  slot_taken: conflicts.length > 0,
  conflicting_posts: conflicts.map(r => ({ post_id: r.post_id, caption: r.caption })),
});
